<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class TrainingEvaluation extends Model{protected $fillable=['company_id','training_topic_id','training_session_id','uuid','title','instructions','evaluation_type','evaluation_phase','passing_score','maximum_attempts','time_limit_minutes','randomize_questions','randomize_options','show_result_immediately','show_correct_answers','requires_reinforcement','requires_confirmed_attendance','issues_internal_certificate','opens_at','closes_at','status','version','published_at','created_by','updated_by'];protected $casts=['passing_score'=>'decimal:2','randomize_questions'=>'boolean','randomize_options'=>'boolean','show_result_immediately'=>'boolean','show_correct_answers'=>'boolean','requires_reinforcement'=>'boolean','requires_confirmed_attendance'=>'boolean','issues_internal_certificate'=>'boolean','opens_at'=>'datetime','closes_at'=>'datetime','published_at'=>'datetime'];public function getRouteKeyName(){return'uuid';}public function session(){return$this->belongsTo(TrainingSession::class,'training_session_id');}public function topic(){return$this->belongsTo(TrainingTopic::class,'training_topic_id');}public function questions(){return$this->hasMany(TrainingEvaluationQuestion::class)->orderBy('sort_order');}public function attempts(){return$this->hasMany(TrainingEvaluationAttempt::class);}public function accesses(){return$this->hasMany(TrainingEvaluationAccess::class);}public function scopeForCompany($q,int$id){return$q->where('company_id',$id);}}
